export type SnakeGameConfig = {
	enabled?: boolean;
	ticketSecretFile?: string;
	enabledFile?: string;
};

/**
 * 設定ファイルの型
 */
type Source = {
	snakeGame?: SnakeGameConfig;
	nativePush?: NativePushConfig;
	url?: string;
	port?: number;
	socket?: string;
	trustProxy?: FastifyServerOptions['trustProxy'];
	chmodSocket?: string;
